from pydantic import BaseModel, Field

class Citation(BaseModel):
    """A cited paper from the provided collection, by title."""
    cited_title: str | None = Field(description="Title of the provided paper being cited")

class Paper(BaseModel):
    """One provided paper: its own title and which of the OTHER provided papers it references."""
    title: str | None = Field(description="This paper's title")
    citations_from_provided_collection: list[Citation] = Field(description="Titles of OTHER provided papers (known from document summaries) that appear in this paper's reference list")

class Parse(BaseModel):
    papers: list[Paper]
